import{_ as o,l as n,o as e,c as l,v as t,p,x as i,d as s,i as _,S as c}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"高峰负荷定价","description":"","frontmatter":{"title":"高峰负荷定价","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/peak-load-pricing.md","filePath":"econ/peak-load-pricing.md","lastUpdated":1789023840000}'),d={name:"econ/peak-load-pricing.md"};function h(E,a,m,u,B,P){const r=n("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="高峰负荷定价" tabindex="-1">高峰负荷定价 <a class="header-anchor" href="#高峰负荷定价" aria-label="Permalink to &quot;高峰负荷定价&quot;">​</a></h1><div class="epigraph"><p>容量在峰时才稀缺；峰时价格应含容量的影子价格，谷时只付运营的边际成本。</p><footer>—— 据 Steiner, Peak Loads and Efficient Pricing, QJE, 1957；Boiteux 论电力高峰负荷整理</footer></div><p>定位：<a href="/econ/two-part-bundling">上一课</a>。两部收费把固定费与使用费拆开，抽取的是<strong>人</strong>的剩余。本课不重讲 \\((A,p)\\) 与捆绑。缺口是同一套产能在<strong>时点</strong>上稀缺：电厂、日内电网、旅馆的床，谷时闲置、峰时打满。容量的成本不该平均摊进每一个小时，而应作为峰时的影子价格出现。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>把一天分成峰 \\(H\\) 与谷 \\(L\\)，运营成本 \\(c\\) 每单位，容量成本 \\(\\beta\\) 按能同时服务的最大负荷收取。容量 \\(K\\) 必须满足 \\(q_H\\le K\\)、\\(q_L\\le K\\)。有效率的价格（福利最大化、可补贴或总额转移可用时）满足：谷时若 \\(q_L\\lt K\\)，则 \\(P_L=c\\)；峰时 \\(q_H=K\\)，则 \\(P_H=c+\\beta\\)（更一般：\\(P_H=c+\\mu\\)，\\(\\mu\\) 是容量约束的乘子）。缺口不是把峰谷写成<a href="/econ/price-discrimination">三级歧视</a>的两个弹性组，而是：<strong>\\(\\beta\\) 由谁在何时支付。</strong></p><p>若峰谷都打满（shifting peak），容量成本在两段需求之间分摊，Steiner 的图解给出交点，使 \\(q_H=q_L=K\\)。不要默认「峰永远独自承担全部 \\(\\beta\\)」。</p><h3 id="高峰负荷不是两部收费的改名" tabindex="-1">高峰负荷不是两部收费的改名 <a class="header-anchor" href="#高峰负荷不是两部收费的改名" aria-label="Permalink to &quot;高峰负荷不是两部收费的改名&quot;">​</a></h3><p>两部的 \\(A\\) 对人收，与用了多少小时可以脱钩。高峰负荷对时点收，同一人在谷时应付 \\(c\\)、在峰时应付 \\(c+\\mu\\)。容量是公共投入，但稀缺发生在峰时，影子价格必须按时点分化。把 \\(\\beta\\) 折进统一的 \\(A\\)，谷时用户会补贴峰时用户，容量会被过度申报。</p><p><span class="marginnote">Boiteux 在电力里同时写过预算约束与高峰负荷。本课先钉无预算约束的有效峰谷价；若还要盈亏平衡，再叠<a href="/econ/natural-monopoly-ramsey">拉姆齐</a>乘子，峰时加价承担更多固定容量。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>规划：\\(\\max\\) 两时段剩余之和，约束 \\(q_t\\le K\\)，成本 \\(c(q_H+q_L)+\\beta K\\)。库恩–塔克给出上述 \\(P_t=c+\\mu_t\\)，\\(\\mu_L\\mu_H\\) 至少有一个等于 \\(\\beta\\) 的互补。需求给定为 \\(D_t(P_t)\\)（可加时段是教具；跨时替代把需求写成交叉价格，乘子仍是容量）。</p><p>比较静态：峰需求外移，\\(\\mu_H\\) 升、\\(K\\) 升；谷需求外移，若仍不满容，只增加 \\(q_L\\)、不建厂。这与长期进入不同：这里「进入」的是容量单位，不是第二家厂商。</p><p>峰谷需求若高度替代，价差会自我限制，Steiner 的 shifting peak 更容易出现。不要把分时价差事先标成「峰永远更贵」而不解乘子。</p>',13)),(e(),p(c,null,{default:i(()=>[_(r,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20CAP%5B%22%E5%AE%B9%E9%87%8F%20K%EF%BC%8C%E6%88%90%E6%9C%AC%20%CE%B2%22%5D%20--%3E%20PK%5B%22%E5%B3%B0%EF%BC%9Aq_H%20%3D%20K%EF%BC%8C%CE%BC_H%20%3E%200%22%5D%0A%20%20CAP%20--%3E%20OF%5B%22%E8%B0%B7%EF%BC%9Aq_L%20%EF%BC%9C%20K%20%E5%88%99%20%CE%BC_L%20%3D%200%22%5D%0A%20%20PK%20--%3E%20PH%5B%22P_H%20%3D%20c%20%2B%20%CE%BC_H%22%5D%0A%20%20OF%20--%3E%20PL%5B%22P_L%20%3D%20c%22%5D%0A%20%20PH%20--%3E%20SHIFT%5B%22%E5%8F%8C%E6%BB%A1%E5%AE%B9%EF%BC%9A%CE%B2%20%E5%9C%A8%E4%B8%A4%E6%AE%B5%E5%88%86%E6%91%8A%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>实施可以用分时线性价，也可以用容量费加能量费——后者像两部，但容量费应按峰时责任分摊，不是按人头。不要把分时价写成限价簿的盘中价差。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>影子价格的机制是稀缺：多给峰时一单位消费，必须扩容一单位，社会成本是 \\(c+\\beta\\)。谷时多消费只动 \\(c\\)，因为 \\(K\\) 已被峰时付过。Steiner 的「谁是峰」由均衡内生：价差会抑制原峰、抬升原谷，直到负荷关系与乘子一致。</p><p>与自然垄断的接口：管网往往既次加又有高峰。拉姆齐处理的是预算，高峰处理的是时点稀缺；两套乘子可以同时存在。与两部的接口：对人收的 \\(A\\) 不能代替 \\(\\mu_H\\)——\\(A\\) 不随峰时用量变，管不住容量申报。</p><p>计量与结算是实施细节：分时表把 \\(P_H,P_L\\) 送给用户；容量责任按峰时负荷份额分摊，则接近两部里「谁造成 \\(K\\) 谁付 \\(\\beta\\)」。统一电价把 \\(\\beta\\) 摊进每一度谷电，谷时过度消费、峰时容量不够，这是把影子价格抹平的代价，不是需求弹性写错。</p><p><span class="marginnote">Steiner 1957 用的是可加的独立时段需求。跨时替代、储能、可中断合同会把「峰」变成可调度的集合，乘子仍在容量约束上，只是 \\(q_t\\) 不再独立。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>随机需求、可靠性约束把 \\(\\beta\\) 换成期望停电损失，本课不写。输电拥堵的节点价是空间版高峰负荷，机制相同、地理不同。零售若不能分时计量，只能退回平均成本，回到次优。储能把谷时电力变成峰时供给，\\(K\\) 的影子价格下降，时段划分变成内生。</p><p>也不要把峰谷价差写成限价簿盘中价差：这里没有时间优先。</p><p>后课默认：容量的边际社会成本出现在打满的那个时段；谷时不满容则不加 \\(\\beta\\)。市场结构主干下一课进入寡占数量竞争，不再扩容时点。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>峰时价格含容量影子价格；谷时不满容只付运营 MC。</li><li>双满容时 \\(\\beta\\) 在时段间分摊，峰的身份是均衡对象。</li><li>不是三级分箱，也不是两部入场费的改名。</li><li>下一课把「一家面对需求」换成几家同时选产量。</li><li>出处：Steiner, <em>QJE</em>, 1957；Boiteux 的电力高峰负荷分析。</li></ul>',12))])}const b=o(d,[["render",h]]);export{C as __pageData,b as default};
